def compute(vars):
    cadence_index = vars["v1"]
    nasdaq_index = vars["v2"]
    cadence_cumulative_return_pct = cadence_index - 100
    nasdaq_cumulative_return_pct = nasdaq_index - 100
    difference_percentage_points = cadence_cumulative_return_pct - nasdaq_cumulative_return_pct

    return {
        "value": difference_percentage_points,
        "trace": {
            "cadence_cumulative_return_pct": cadence_cumulative_return_pct,
            "nasdaq_cumulative_return_pct": nasdaq_cumulative_return_pct,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
